//! Writes the store: the certificates sorted by subject Name, their DER concatenated as
//! `roots.der`, and `bundle.rs`, which carries the snapshot date, includes `roots.der`, and indexes
//! each certificate by its subject with the offset and length of its DER. The sort is stable, so
//! certificates that share a subject keep the order of the input.

use std::fmt::Write as _;

use crate::der;
use crate::pem::Block;

/// The opening lines of `bundle.rs`: three `//~` lines naming this tool, then a blank line.
const HEADER: [&str; 4] = [
    "//~ @generated by lamella-tls-roots-gen from the official curl/Mozilla CA bundle (cacert.pem);",
    "//~ do not edit by hand -- regenerate instead. The DER lives in roots.der (include_bytes!);",
    "//~ this is the SUBJECT-DN index, sorted for a binary search by a child's issuer DN.",
    "",
];

/// The lines of `bundle.rs` before the snapshot date's.
const BEFORE_SNAPSHOT: [&str; 3] = [
    "/// The upstream bundle's \"Certificate data from Mozilla as of\" snapshot -- the store ages",
    "/// (roots are added, distrusted, and expire), so a long-lived device should refresh it or",
    "/// pin its own certificate instead.",
];

/// The lines of `bundle.rs` between the snapshot date's and the first index entry.
const BEFORE_INDEX: [&str; 8] = [
    "",
    "/// The concatenated DER of every bundled root certificate.",
    "pub(crate) static ROOT_DER: &[u8] = include_bytes!(\"roots.der\");",
    "",
    "/// `(subject_dn_der, offset, len)` for each root, sorted by `subject_dn_der`. The offset/len",
    "/// slice `ROOT_DER`; the subject DN is the exact bytes mbedTLS compares against a child's",
    "/// issuer DN, so a lookup is a binary search over these.",
    "pub(crate) static ROOT_INDEX: &[(&[u8], u32, u32)] = &[",
];

/// The generated store: the contents of `roots.der` and of `bundle.rs`, and how many roots they
/// hold.
pub(crate) struct Store {
    pub(crate) der: Vec<u8>,
    pub(crate) rust: String,
    pub(crate) roots: usize,
}

/// The store for `blocks`, whose Mozilla snapshot is dated `snapshot`.
pub(crate) fn store(snapshot: &str, blocks: &[Block]) -> Result<Store, String> {
    struct Entry<'a> {
        subject: &'a [u8],
        der: &'a [u8],
    }
    let mut entries = Vec::with_capacity(blocks.len());
    for block in blocks {
        let subject = der::subject(&block.der)
            .map_err(|error| format!("the certificate at line {}: {error}", block.line))?;
        entries.push(Entry {
            subject,
            der: &block.der,
        });
    }
    entries.sort_by_key(|entry| entry.subject);

    let mut rust = String::new();
    for line in HEADER.iter().chain(&BEFORE_SNAPSHOT) {
        rust.push_str(line);
        rust.push('\n');
    }
    let _ = writeln!(
        rust,
        "pub(crate) static MOZILLA_SNAPSHOT: &str = \"{}\";",
        snapshot.escape_default()
    );
    for line in BEFORE_INDEX {
        rust.push_str(line);
        rust.push('\n');
    }
    let mut der = Vec::new();
    for entry in &entries {
        let offset = offset_in_u32(der.len())?;
        let length = offset_in_u32(entry.der.len())?;
        der.extend_from_slice(entry.der);
        rust.push_str("    (b\"");
        for byte in entry.subject {
            let _ = write!(rust, "\\x{byte:02x}");
        }
        let _ = writeln!(rust, "\", {offset}, {length}),");
    }
    offset_in_u32(der.len())?;
    rust.push_str("];\n");
    Ok(Store {
        der,
        rust,
        roots: entries.len(),
    })
}

/// `value` as the `u32` an index entry holds; the index cannot address a `roots.der` of 4 GiB.
fn offset_in_u32(value: usize) -> Result<u32, String> {
    u32::try_from(value)
        .map_err(|_| format!("{value} bytes of DER is more than the index's u32 offsets address"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pem;

    /// The store as `lamella-tls-roots`, the crate beside this one, holds it.
    const COMMITTED_DER: &[u8] = include_bytes!("../../lamella-tls-roots/src/roots.der");
    const COMMITTED_RUST: &str = include_str!("../../lamella-tls-roots/src/bundle.rs");

    /// Base64 in the standard alphabet, padded, as a PEM body carries it.
    fn encode_base64(bytes: &[u8]) -> String {
        const ALPHABET: &[u8; 64] =
            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let mut text = String::new();
        for group in bytes.chunks(3) {
            let mut value = [0u8; 3];
            value[..group.len()].copy_from_slice(group);
            let value = u32::from_be_bytes([0, value[0], value[1], value[2]]);
            for position in 0..4 {
                if position <= group.len() {
                    text.push(char::from(
                        ALPHABET[(value >> (18 - 6 * position) & 0x3f) as usize],
                    ));
                } else {
                    text.push('=');
                }
            }
        }
        text
    }

    /// A store file as curl writes one: the snapshot line, then each certificate as a block with
    /// 64-symbol lines.
    fn pem_file(snapshot: &str, certificates: &[&[u8]]) -> String {
        let mut text = format!("##\n## Certificate data from Mozilla as of: {snapshot}\n##\n");
        for certificate in certificates {
            text.push_str("\nSome Root CA\n============\n-----BEGIN CERTIFICATE-----\n");
            for line in encode_base64(certificate).as_bytes().chunks(64) {
                text.push_str(std::str::from_utf8(line).unwrap());
                text.push('\n');
            }
            text.push_str("-----END CERTIFICATE-----\n");
        }
        text
    }

    fn generate(text: &str) -> Store {
        store(
            pem::snapshot(text).unwrap(),
            &pem::certificates(text).unwrap(),
        )
        .unwrap()
    }

    #[test]
    fn base64_encoding_here_agrees_with_the_decoder() {
        for length in 0..8 {
            let bytes: Vec<u8> = (0..length).map(|i| (i * 37 + 11) as u8).collect();
            let text = pem_file("today", &[&bytes]);
            let blocks = pem::certificates(&text).unwrap();
            assert_eq!(blocks[0].der, bytes, "length {length}");
        }
    }

    #[test]
    fn the_committed_store_is_what_this_tool_generates() {
        let mut certificates = Vec::new();
        let mut rest = COMMITTED_DER;
        while !rest.is_empty() {
            let (element, after) = der::read_element(rest).unwrap();
            certificates.push(element.encoding);
            rest = after;
        }
        let snapshot = COMMITTED_RUST
            .lines()
            .find_map(|line| line.strip_prefix("pub(crate) static MOZILLA_SNAPSHOT: &str = \""))
            .and_then(|rest| rest.strip_suffix("\";"))
            .expect("bundle.rs states MOZILLA_SNAPSHOT");

        let generated = generate(&pem_file(snapshot, &certificates));
        assert_eq!(generated.roots, certificates.len());
        assert!(
            generated.der == COMMITTED_DER,
            "roots.der differs from what this tool generates"
        );

        let header: String = HEADER.iter().map(|line| format!("{line}\n")).collect();
        let body = generated
            .rust
            .strip_prefix(&header)
            .expect("the generated file opens with the header");
        let Some(front) = COMMITTED_RUST.strip_suffix(body) else {
            let first_difference = COMMITTED_RUST
                .lines()
                .rev()
                .zip(body.lines().rev())
                .position(|(committed, generated)| committed != generated)
                .map_or(0, |from_end| COMMITTED_RUST.lines().count() - from_end);
            panic!("bundle.rs differs from what this tool generates, at line {first_difference}");
        };
        assert!(
            front
                .lines()
                .all(|line| line.is_empty() || line.starts_with("//~")),
            "bundle.rs opens with {front:?}"
        );
    }

    #[test]
    fn the_index_is_sorted_by_subject_and_shared_subjects_keep_their_order() {
        fn certificate(subject: u8, serial: u8) -> Vec<u8> {
            let name = [0x30, 0x03, 0x0c, 0x01, subject];
            let mut tbs = vec![0x02, 0x01, serial, 0x30, 0x00, 0x30, 0x00, 0x30, 0x00];
            tbs.extend_from_slice(&name);
            let mut certificate = vec![0x30, tbs.len() as u8 + 7, 0x30, tbs.len() as u8];
            certificate.extend_from_slice(&tbs);
            certificate.extend_from_slice(&[0x30, 0x00, 0x03, 0x01, 0x00]);
            certificate
        }
        let (b1, a, b2) = (
            certificate(b'b', 1),
            certificate(b'a', 2),
            certificate(b'b', 3),
        );
        let generated = generate(&pem_file("then", &[&b1, &a, &b2]));
        assert_eq!(generated.der, [a.as_slice(), &b1, &b2].concat());
        let entries: Vec<&str> = generated
            .rust
            .lines()
            .filter(|line| line.starts_with("    (b\""))
            .collect();
        assert_eq!(
            entries,
            [
                format!("    (b\"\\x30\\x03\\x0c\\x01\\x61\", 0, {}),", a.len()),
                format!(
                    "    (b\"\\x30\\x03\\x0c\\x01\\x62\", {}, {}),",
                    a.len(),
                    b1.len()
                ),
                format!(
                    "    (b\"\\x30\\x03\\x0c\\x01\\x62\", {}, {}),",
                    a.len() + b1.len(),
                    b2.len()
                ),
            ]
        );
        assert!(
            generated
                .rust
                .contains("MOZILLA_SNAPSHOT: &str = \"then\";\n")
        );
        assert!(generated.rust.ends_with("),\n];\n"));
    }

    #[test]
    fn a_certificate_that_does_not_parse_is_named_by_its_line() {
        let text = pem_file("now", &[&[0x30, 0x00]]);
        let error = store(
            pem::snapshot(&text).unwrap(),
            &pem::certificates(&text).unwrap(),
        )
        .err()
        .unwrap();
        assert!(
            error.starts_with("the certificate at line 7: tbsCertificate: truncated"),
            "{error}"
        );
    }
}
